// Define the structure for an FSA node
typedef struct FsaNode {
    int data;
    struct FsaNode* next;
} FsaNode;

// Function to create a new state list in the given finite state automaton (FSA)
FsaNode** create_state_list(int* states, int num_states, FsaNode* fsa, int last_state) {
    // Check if there is insufficient memory
    if (!states || !fsa) {
        return NULL;
    }

    // Allocate space for the new state list on the heap
    FsaNode** new_state_list = (FsaNode**)malloc(sizeof(FsaNode*));

    // Initialize the current state to 0 and the index in the states array to 0
    int curr_state = 0;
    int idx = 0;

    // Iterate over the range of given states to create a new state list
    while (idx < num_states) {
        // Allocate space for a new FSA node on the heap
        FsaNode* new_node = (FsaNode*)malloc(sizeof(FsaNode));

        // Store the current state in the new node
        new_node->data = states[idx];

        // If this is not the last state, point its 'next' to NULL
        if (idx < num_states - 1) {
            new_node->next = NULL;
        }
        // If this is the last state, update its 'next' to point to the newly created state list
        else {
            new_node->next = *new_state_list;

            // Update the 'next' pointer of the last state in the list to point to the newly created state list
            fsa[last_state].next = *new_state_list;
        }

        // Add the new node to the new state list and increment the index
        *new_state_list = new_node;
        idx++;
    }

    // Return a pointer to the newly created state list
    return new_state_list;
}
